WITH flattened_attrs AS (SELECT id, log_ts, status_code, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, DATE_TRUNC('DAY', log_ts) AS activity_day, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, BIT_AND(status_code) AS status_code_bit_and FROM flattened_attrs GROUP BY CUBE (DATE_TRUNC('HOUR', log_ts), DATE_TRUNC('DAY', log_ts)) HAVING status_code_bit_and > 1 ORDER BY hour_window DESC NULLS LAST
